// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.infrastructureimport timber.log.Timberimport com.roshan.persona.vision.core.ModelManagerimport com.roshan.persona.vision.memory.VisualEpisodicMemoryimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContextimport java.io.File/** * NOUS — LMK Eviction Orchestrator (Module 6 v4 — Step 6.7, CRITICAL). * * Implements the **3-second evacuation protocol** to survive Android's Low * Memory Killer (LMK) on 3-4 GB RAM devices, per strategy v4 §"Critical * Engineering Fix 3: Android LMK Survival". * * ## Why this matters * * On a 3 GB RAM device (low-end tier), NOUS's vision module uses ~330 MB * (Omni-SLM INT2 290 MB + KV cache 40 MB + ring buffer 0.3 MB). When the user * switches to WhatsApp or YouTube, Android's LMK can kill NOUS's background * processes or evict the Omni-SLM from RAM — destroying the 200 ms cold-start * promise. * * The LMK Eviction Orchestrator detects when the camera UI minimizes * (ActivityLifecycleCallback.onStop) and executes a 3-second evacuation: * * ``` * T+0ms: Camera UI minimizes (ActivityLifecycleCallback.onStop) *   ↓ * T+50ms: Serialize Visual Episodic Memory ring buffer (~300 KB) *   - AES-256-GCM encrypt *   - Write to episodic_cache.enc *   - Clear ring buffer from RAM *   ↓ * T+500ms: Flush Omni-SLM KV cache to disk (if dirty) *   - zstd compress 140 MB → 35 MB *   - Write to kv_cache.zst.enc *   - Clear KV cache from RAM *   ↓ * T+1000ms: Release Omni-SLM weights from RAM *   - Free 580 MB (INT4) or 290 MB (INT2) *   - Mark model as "unloaded but cached on disk" *   ↓ * T+1500ms: Release SSD MobileNetV3 + ML Kit models *   - Free additional 50 MB *   ↓ * T+2000ms: Vision module fully evicted from RAM *   - Total freed: 725 MB (high tier) / 330 MB (low tier) *   - NOUS now uses < 50 MB RAM in background *   - LMK will NOT kill NOUS * ``` * * ## Re-activation (camera UI reopens) * * ``` * T+0ms: ActivityLifecycleCallback.onStart *   ↓ * T+200ms: Reload Omni-SLM weights from disk (mmap, warm cache) *   ↓ * T+400ms: Restore KV cache from disk *   ↓ * T+500ms: Restore episodic memory ring buffer *   ↓ * T+600ms: Vision ready (user perceives ~600 ms "wake up" delay) * ``` * * ## Persistent Vision Mode (opt-in) * * For accessibility users who need instant wake-up, NOUS offers a Persistent * Vision Mode (Settings → Battery → Persistent Vision): *  - Sticky foreground notification: "NOUS Vision is active" *  - Prevents LMK from killing NOUS *  - Trade-off: Continuous 50-80 mA draw (Omni-SLM weights kept resident) * * ## Testability * * [EvictionTarget] abstracts the actual eviction operations. Tests inject * [FakeEvictionTarget] to verify timing + ordering without real model loading. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Critical Engineering Fix 3: LMK Survival</a> */class LmkEvictionOrchestrator(    private val target: EvictionTarget,    private val dispatcher: CoroutineDispatcher,) {    /** True if evacuation is currently in progress. */    @Volatile    private var evacuationInProgress: Boolean = false    /** True if Persistent Vision Mode is enabled (opt-in, prevents eviction). */    @Volatile    private var persistentModeEnabled: Boolean = false    /** Total evacuations performed (for stats). */    @Volatile    private var totalEvacuations: Int = 0    /** Total reactivations performed (for stats). */    @Volatile    private var totalReactivations: Int = 0    /** Last evacuation duration (ms). */    @Volatile    private var lastEvacuationMs: Long = 0L    /** Last reactivation duration (ms). */    @Volatile    private var lastReactivationMs: Long = 0L    /**     * Execute the 3-second evacuation protocol.     *     * Called when the camera UI minimizes (ActivityLifecycleCallback.onStop).     *     * @return the [EvacuationResult] — SUCCESS, SKIPPED (persistent mode), or FAILED.     */    suspend fun evacuate(): EvacuationResult = withContext(dispatcher) {        if (persistentModeEnabled) {            Timber.tag(TAG).i("Evacuation skipped — Persistent Vision Mode is active.")            return@withContext EvacuationResult.SKIPPED_PERSISTENT_MODE        }        if (evacuationInProgress) {            Timber.tag(TAG).w("Evacuation already in progress — skipping.")            return@withContext EvacuationResult.SKIPPED_ALREADY_IN_PROGRESS        }        evacuationInProgress = true        val startTime = System.currentTimeMillis()        Timber.tag(TAG).i("LMK evacuation protocol started.")        val stepResults = mutableListOf<EvacuationStep>()        try {            // Step 1: Serialize episodic memory ring buffer (50 ms budget).            val step1Start = System.currentTimeMillis()            val episodicSuccess = target.serializeEpisodicMemory()            val step1Ms = System.currentTimeMillis() - step1Start            stepResults.add(EvacuationStep("serialize_episodic_memory", step1Ms, episodicSuccess))            if (!episodicSuccess) {                Timber.tag(TAG).w("Episodic memory serialization failed — continuing with eviction anyway.")            }            // Step 2: Flush KV cache (450 ms budget).            val step2Start = System.currentTimeMillis()            val kvSuccess = target.flushKvCache()            val step2Ms = System.currentTimeMillis() - step2Start            stepResults.add(EvacuationStep("flush_kv_cache", step2Ms, kvSuccess))            // Step 3: Release Omni-SLM weights (500 ms budget).            val step3Start = System.currentTimeMillis()            val omniSlmSuccess = target.evictOmniSlm()            val step3Ms = System.currentTimeMillis() - step3Start            stepResults.add(EvacuationStep("evict_omni_slm", step3Ms, omniSlmSuccess))            // Step 4: Release SSD + ML Kit models (500 ms budget).            val step4Start = System.currentTimeMillis()            val otherModelsSuccess = target.evictOtherModels()            val step4Ms = System.currentTimeMillis() - step4Start            stepResults.add(EvacuationStep("evict_other_models", step4Ms, otherModelsSuccess))            val totalMs = System.currentTimeMillis() - startTime            lastEvacuationMs = totalMs            totalEvacuations++            val allSuccess = stepResults.all { it.success }            Timber.tag(TAG).i("LMK evacuation complete in ${totalMs}ms (allSuccess=$allSuccess).")            return@withContext if (allSuccess) {                EvacuationResult.SUCCESS(totalMs, stepResults)            } else {                EvacuationResult.PARTIAL(totalMs, stepResults)            }        } catch (t: Throwable) {            val totalMs = System.currentTimeMillis() - startTime            Timber.tag(TAG).e("LMK evacuation failed after ${totalMs}ms.", t)            return@withContext EvacuationResult.FAILED(totalMs, t.message ?: "Unknown error")        } finally {            evacuationInProgress = false        }    }    /**     * Reactivate the vision module after evacuation.     *     * Called when the camera UI reopens (ActivityLifecycleCallback.onStart).     *     * @return the [ReactivationResult] — SUCCESS or FAILED.     */    suspend fun reactivate(): ReactivationResult = withContext(dispatcher) {        val startTime = System.currentTimeMillis()        Timber.tag(TAG).i("Vision reactivation started.")        try {            // Step 1: Reload Omni-SLM weights (200 ms budget).            val omniSlmLoaded = target.reloadOmniSlm()            // Step 2: Restore KV cache (200 ms budget).            val kvRestored = target.restoreKvCache()            // Step 3: Restore episodic memory (100 ms budget).            val episodicRestored = target.restoreEpisodicMemory()            val totalMs = System.currentTimeMillis() - startTime            lastReactivationMs = totalMs            totalReactivations++            val allSuccess = omniSlmLoaded && kvRestored && episodicRestored            Timber.tag(TAG).i("Reactivation complete in ${totalMs}ms (omniSlm=$omniSlmLoaded, kv=$kvRestored, episodic=$episodicRestored).")            return@withContext if (allSuccess) {                ReactivationResult.SUCCESS(totalMs)            } else {                ReactivationResult.PARTIAL(totalMs, omniSlmLoaded, kvRestored, episodicRestored)            }        } catch (t: Throwable) {            val totalMs = System.currentTimeMillis() - startTime            Timber.tag(TAG).e("Reactivation failed after ${totalMs}ms.", t)            return@withContext ReactivationResult.FAILED(totalMs, t.message ?: "Unknown error")        }    }    /**     * Enable Persistent Vision Mode (prevents eviction — for accessibility users).     */    fun enablePersistentMode() {        persistentModeEnabled = true        Timber.tag(TAG).i("Persistent Vision Mode enabled — eviction will be skipped.")    }    /** Disable Persistent Vision Mode. */    fun disablePersistentMode() {        persistentModeEnabled = false        Timber.tag(TAG).i("Persistent Vision Mode disabled — eviction will run on minimize.")    }    /** True if Persistent Vision Mode is active. */    fun isPersistentModeEnabled(): Boolean = persistentModeEnabled    /** True if evacuation is currently in progress. */    fun isEvacuationInProgress(): Boolean = evacuationInProgress    /** Get stats (for Settings UI). */    fun stats(): EvictionStats = EvictionStats(        totalEvacuations = totalEvacuations,        totalReactivations = totalReactivations,        lastEvacuationMs = lastEvacuationMs,        lastReactivationMs = lastReactivationMs,        persistentModeEnabled = persistentModeEnabled,        evacuationInProgress = evacuationInProgress,    )    private companion object {        private const val TAG = "LmkEviction"    }}// ──────────────────────────────────────────────────────────────────────────/** Result of [LmkEvictionOrchestrator.evacuate]. */sealed interface EvacuationResult {    data class SUCCESS(        val totalMs: Long,        val steps: List<EvacuationStep>,    ) : EvacuationResult    data class PARTIAL(        val totalMs: Long,        val steps: List<EvacuationStep>,    ) : EvacuationResult    data class FAILED(        val totalMs: Long,        val errorMessage: String,    ) : EvacuationResult    data object SKIPPED_PERSISTENT_MODE : EvacuationResult    data object SKIPPED_ALREADY_IN_PROGRESS : EvacuationResult}/** Result of [LmkEvictionOrchestrator.reactivate]. */sealed interface ReactivationResult {    data class SUCCESS(val totalMs: Long) : ReactivationResult    data class PARTIAL(        val totalMs: Long,        val omniSlmLoaded: Boolean,        val kvRestored: Boolean,        val episodicRestored: Boolean,    ) : ReactivationResult    data class FAILED(        val totalMs: Long,        val errorMessage: String,    ) : ReactivationResult}/** One step in the evacuation protocol. */data class EvacuationStep(    val name: String,    val durationMs: Long,    val success: Boolean,)/** Stats for Settings UI. */data class EvictionStats(    val totalEvacuations: Int,    val totalReactivations: Int,    val lastEvacuationMs: Long,    val lastReactivationMs: Long,    val persistentModeEnabled: Boolean,    val evacuationInProgress: Boolean,)// ──────────────────────────────────────────────────────────────────────────/** * Eviction target interface — abstracts the actual model + cache operations. * * Production: [VisionEvictionTarget] wraps ModelManager + VisualEpisodicMemory * + KV cache store. * Tests: [FakeEvictionTarget] records calls + returns configurable results. */interface EvictionTarget {    /** Serialize episodic memory to encrypted disk cache. */    suspend fun serializeEpisodicMemory(): Boolean    /** Flush Omni-SLM KV cache to compressed disk cache. */    suspend fun flushKvCache(): Boolean    /** Release Omni-SLM weights from RAM. */    suspend fun evictOmniSlm(): Boolean    /** Release SSD + ML Kit models from RAM. */    suspend fun evictOtherModels(): Boolean    /** Reload Omni-SLM weights from disk (mmap). */    suspend fun reloadOmniSlm(): Boolean    /** Restore KV cache from compressed disk cache. */    suspend fun restoreKvCache(): Boolean    /** Restore episodic memory from encrypted disk cache. */    suspend fun restoreEpisodicMemory(): Boolean}
